import { useMemo, useState, type ReactNode } from "react";
import { useOutlet } from "react-router-dom";
import Box from "@mui/material/Box";
import useMediaQuery from "@mui/material/useMediaQuery";
import AppRegistrationIcon from "@mui/icons-material/AppRegistration";
import DashboardIcon from "@mui/icons-material/Dashboard";
import SettingsIcon from "@mui/icons-material/Settings";
import TaskAltIcon from "@mui/icons-material/TaskAlt";
import AppHeader from "./AppHeader";
import Sidebar, { type NavItem } from "./Sidebar";

interface DashboardLayoutProps {
  appTodo?: () => ReactNode;
  title?: string;
}

export interface DashboardOutletContext {
  appTodo?: () => ReactNode;
  setPageTitle: (title: string) => void;
}

export const drawerWidth = 264;

const navItems: NavItem[] = [
  { label: "Dashboard", icon: DashboardIcon, path: "/dashboard" },
  { label: "Zadania", icon: TaskAltIcon, path: "/tasks" },
  { label: "Ustawienia", icon: SettingsIcon, path: "/settings" },
  { label: "Rejestracja", icon: AppRegistrationIcon, path: "/register" },
];

export default function DashboardLayout({
  appTodo,
  title = "Dashboard",
}: DashboardLayoutProps) {
  const isDesktop = useMediaQuery("(min-width:900px)");
  const [pageTitle, setPageTitle] = useState(title);
  const outletContext = useMemo(() => ({ appTodo, setPageTitle }), [appTodo]);
  const outlet = useOutlet(outletContext);

  return (
    <Box
      component="section"
      aria-label="Układ pulpitu"
      sx={{ minHeight: "100vh", bgcolor: "background.default" }}
    >
      {isDesktop ? <Sidebar navItems={navItems} /> : null}
      <Box
        id="main-content"
        component="main"
        tabIndex={-1}
        aria-label="Główna zawartość aplikacji"
        sx={{
          minHeight: "100vh",
          width: isDesktop ? `calc(100% - ${drawerWidth}px)` : "100%",
          ml: isDesktop ? `${drawerWidth}px` : 0,
          bgcolor: "background.default",
          px: { xs: 2, sm: 3 },
          pb: 4,
          overflow: "hidden",
        }}
      >
        <AppHeader navItems={navItems} title={pageTitle} isDesktop={isDesktop} />
        <Box sx={{ height: 96 }} />
        {outlet}
      </Box>
    </Box>
  );
}
